import {displayCity} from './lib/discovery/destination-identity.js';
import {displayLabel} from './lib/display-localization.js';
import {LocalDestinationVisualProvider} from './lib/discovery/destination-visual-provider.js';
import {destinationIdentity} from './lib/discovery/destination-identity.js';
import {navigationForCountry} from './lib/providers/navigation-provider.js';

const visualProvider=new LocalDestinationVisualProvider();
const e=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const label=(language,zh,en)=>language==='zh'?zh:en;
export const MAX_TRIP_COLLAGE_IMAGES=2;

const shortDate=(value,language)=>value?new Date(`${value.slice(0,10)}T00:00:00Z`).toLocaleDateString(language==='zh'?'zh-CN':'en-US',{month:'short',day:'numeric',timeZone:'UTC'}):'';
const shortTime=value=>/^\d{4}-\d\d-\d\dT\d\d:\d\d/.test(value||'')?value.slice(11,16):null;
const duration=(from,to)=>{if(!from||!to)return null;const minutes=Math.round((Date.parse(to)-Date.parse(from))/60000);return Number.isFinite(minutes)&&minutes>0?minutes:null;};
const durationText=(minutes,language)=>minutes==null?'':language==='zh'?`${Math.floor(minutes/60)}小时${minutes%60?`${minutes%60}分`:''}`:`${Math.floor(minutes/60)}h ${minutes%60?`${minutes%60}m`:''}`;
const paceLabel=(pace,language)=>({relaxed:label(language,'轻松游','Relaxed'),balanced:label(language,'经典体验','Balanced'),intensive:label(language,'高效打卡','Intensive'),deep_dive:label(language,'深度体验','Deep dive')})[pace]||label(language,'经典体验','Balanced');
const spendingLabel=(value,language)=>value==='comfort'?label(language,'舒适优先','Comfort'):label(language,'性价比','Value');

export function tripHeroImages(destination){const visual=visualProvider.getVisual(destination),primary=visual.heroImages[0],secondary=visual.scenicImages[0]||primary;return [primary,secondary].filter(Boolean).slice(0,MAX_TRIP_COLLAGE_IMAGES);}
export function renderTripHero(experience,language='zh'){
 const city=displayCity(experience.trip.destination,language),images=tripHeroImages(experience.trip.destination),window=experience.plan?.windows?.[0];
 const dates=window?`${shortDate(window.departure,language)}–${shortDate(window.returnDate,language)}`:label(language,'日期灵活','Flexible dates');
 return `<div class="trip-hero"><div class="trip-hero-copy"><span>${label(language,'途米先为你准备的基础方案','A COMPLETE STARTING PLAN')}</span><strong>${e(city)} · ${e(experience.trip.nights)}${label(language,'晚',' nights')}</strong><small>${e(dates)}</small><p>${e(paceLabel(experience.itinerary.pace,language))} · ${e(spendingLabel(experience.trip.spendingOrientation,language))}</p><div class="trip-summary-actions"><button type="button" data-trip-action="date">${label(language,'更换日期','Change dates')}</button><button type="button" data-trip-action="duration">${label(language,'调整天数','Change length')}</button><button type="button" data-trip-action="style">${label(language,'调整旅行方式','Change trip style')}</button></div></div><div class="trip-hero-images" aria-hidden="true">${images.map((image,index)=>`<img class="${index?'trip-hero-small':'trip-hero-large'}" src="${e(image.src)}" alt="" loading="lazy">`).join('')}<i class="trip-stamp-motif"></i></div></div>`;
}

export function renderFlightDetails(quote,source,language='zh',route=null){
 if(!quote)return `<p class="trip-availability">${label(language,'航班时间与价格尚未核验','Flight times and price are not verified')}</p>`;
 const segments=Array.isArray(quote.segments)?quote.segments:[],outbound=segments.filter(segment=>segment.slice==='outbound'),inbound=segments.filter(segment=>segment.slice==='return');
 const leg=(items,departure,heading)=>{const first=items[0],last=items.at(-1),start=first?.departingAt||departure,end=last?.arrivingAt||null,times=start&&end?`${shortTime(start)}–${shortTime(end)}`:null,legRoute=first?.origin&&last?.destination?`${first.origin} → ${last.destination}`:null;return `<div class="flight-leg"><b>${heading}</b><span>${legRoute?`${e(legRoute)} · `:''}${start?`${e(shortDate(start,language))} · `:''}${times?e(times):label(language,'到达时间待提供','Arrival time unavailable')}</span>${times?`<small>${e(durationText(duration(start,end),language))}</small>`:''}</div>`;};
 const sourceLabel=source==='live'?label(language,'已核验 · Duffel','Verified · Duffel'):label(language,'演示航班参考','Demo flight reference');
 const stopText=quote.stops===0?label(language,'直飞','Nonstop'):Number.isInteger(quote.stops)?label(language,`${quote.stops} 次中转`,`${quote.stops} stop${quote.stops===1?'':'s'}`):'';
 const amount=quote.currency==='CNY'&&Number.isFinite(quote.price)?`¥${Math.round(quote.price).toLocaleString('en-US')}`:label(language,'价格待核验','Price unverified');
 return `<div class="flight-summary"><span>${e(sourceLabel)}</span>${route?`<span>${e(route.from)} → ${e(route.to)}</span>`:''}<strong>${e(amount)}</strong><small>${e(stopText)}${quote.airline?` · ${e(quote.airline)}`:''}</small></div><details class="flight-details"><summary>${label(language,'查看航班','View flight')}</summary>${outbound.length?leg(outbound,quote.departureDateTime,label(language,'去程','Outbound')):quote.departureDateTime?`<p>${label(language,'去程出发','Outbound departure')} ${e(shortDate(quote.departureDateTime,language))} ${e(shortTime(quote.departureDateTime)||'')} · ${label(language,'到达时间待提供','Arrival time unavailable')}</p>`:`<p>${label(language,'航班时间暂未提供','Flight times unavailable')}</p>`}${inbound.length?leg(inbound,quote.returnDateTime,label(language,'返程','Return')):quote.returnDateTime?`<p>${label(language,'返程出发','Return departure')} ${e(shortDate(quote.returnDateTime,language))} ${e(shortTime(quote.returnDateTime)||'')} · ${label(language,'到达时间待提供','Arrival time unavailable')}</p>`:''}</details>`;
}

export function renderTripTimingControls(experience,language='zh',openPanel=null){
 const plan=experience.plan,window=plan?.windows?.[0],nights=experience.trip.nights,pace=experience.itinerary.pace,spending=experience.trip.spendingOrientation||'value';
 const dates=window?`${shortDate(window.departure,language)} – ${shortDate(window.returnDate,language)}`:label(language,'日期灵活','Flexible dates');
 const budget=experience.trip.flightBudget==null&&experience.trip.hotelBudget==null?label(language,'预算未设','No budget set'):label(language,'已设置预算','Budget set');
 const paceOptions=[['relaxed','轻松游','Relaxed'],['balanced','经典体验','Balanced'],['intensive','高效打卡','Intensive']];
 const spendOptions=[['value','性价比','Value'],['comfort','舒适优先','Comfort']];
 return `<section class="trip-module trip-timing" data-trip-module="timing"><div class="trip-module-heading"><span>01</span><h3>${label(language,'什么时候去','Timing')}</h3></div><p class="trip-current-label">${label(language,'当前推荐','CURRENT PLAN')}</p><p class="trip-current-date"><strong>${e(dates)}</strong> · ${e(nights)} ${label(language,'晚','nights')}</p><p class="trip-availability">${plan?.dateSource==='user_provided'?label(language,'你提供的日期','Your dates'):label(language,'系统探索日期 · 尚未锁定','Provisional exploration dates · not locked')} · ${budget}</p><div class="trip-actions"><button type="button" data-trip-action="date">${label(language,'更换日期','Change dates')}</button><button type="button" data-trip-action="duration">${label(language,'调整天数','Change length')}</button></div><div class="trip-style-controls"><div><span>${label(language,'旅行节奏','Travel pace')}</span><div class="trip-pace" role="group" aria-label="${label(language,'旅行节奏','Travel pace')}">${paceOptions.map(([key,zh,en])=>`<button type="button" data-trip-pace="${key}" aria-pressed="${pace===key}">${label(language,zh,en)}</button>`).join('')}</div></div><div><span>${label(language,'花费取向','Spending orientation')}</span><div class="trip-spending" role="group" aria-label="${label(language,'花费取向','Spending orientation')}">${spendOptions.map(([key,zh,en])=>`<button type="button" data-trip-spending="${key}" aria-pressed="${spending===key}">${label(language,zh,en)}</button>`).join('')}</div></div></div><div class="trip-inline-editor" data-trip-editor="date" ${openPanel==='date'?'':'hidden'}><p>${label(language,'选择探索范围','Explore dates')}</p><div class="trip-actions">${[['3',label(language,'前后3天','±3 days')],['7',label(language,'前后7天','±7 days')],['month',label(language,'本月再找几组','More this month')]].map(([value,text])=>`<button type="button" data-trip-date-option="${value}">${text}</button>`).join('')}<button type="button" data-trip-date-option="custom">${label(language,'自定义日期','Custom dates')}</button></div><div class="trip-custom-dates"><label>${label(language,'出发','Depart')}<input type="date" data-trip-field="departure" value="${e(window?.departure||'')}"></label><label>${label(language,'返程','Return')}<input type="date" data-trip-field="return" value="${e(window?.returnDate||'')}"></label><button type="button" data-trip-action="apply-date">${label(language,'应用','Apply')}</button></div><p class="trip-editor-feedback" aria-live="polite"></p></div><div class="trip-inline-editor" data-trip-editor="duration" ${openPanel==='duration'?'':'hidden'}><p>${label(language,'旅行几晚？','How many nights?')}</p><div class="trip-actions">${[3,4,5,6,7].map(value=>`<button type="button" data-trip-nights="${value}">${value}${label(language,'晚',' nights')}</button>`).join('')}</div><label>${label(language,'自定义','Custom')}<input type="number" min="1" max="30" data-trip-field="nights" value="${e(nights)}"></label><button type="button" data-trip-action="apply-duration">${label(language,'应用','Apply')}</button></div></section>`;
}

const band=(value,language)=>({low:label(language,'低','Low'),medium:label(language,'中','Medium'),high:label(language,'高','High'),short:label(language,'短','Short'),long:label(language,'长','Long')})[value]||value;
export function renderRoutePreview(day,language='zh'){
 const activities=day.activities||[];if(!activities.length)return '';
 const points=activities.map(activity=>activity.place.coordinates).filter(point=>Number.isFinite(point?.lat)&&Number.isFinite(point?.lon));
 const names=activities.map(activity=>activity.place.names[language==='zh'?'zh':'en']);
 if(points.length===activities.length&&points.length>1){const lats=points.map(p=>p.lat),lons=points.map(p=>p.lon),minLat=Math.min(...lats),maxLat=Math.max(...lats),minLon=Math.min(...lons),maxLon=Math.max(...lons),coords=points.map(point=>({x:12+(point.lon-minLon)/(maxLon-minLon||1)*76,y:12+(maxLat-point.lat)/(maxLat-minLat||1)*56}));return `<div class="route-preview route-map" aria-label="${label(language,'当日路线预览','Daily route preview')}"><svg viewBox="0 0 100 80" role="img" aria-label="${e(names.join(' → '))}"><path d="M ${coords.map(p=>`${p.x} ${p.y}`).join(' L ')}"></path>${coords.map((p,index)=>`<g><circle cx="${p.x}" cy="${p.y}" r="6"></circle><text x="${p.x}" y="${p.y+2}">${index+1}</text></g>`).join('')}</svg><ol>${names.map((name,index)=>`<li><b>${index+1}</b>${e(name)}</li>`).join('')}</ol></div>`;}
 return `<div class="route-preview route-diagram" aria-label="${label(language,'当日顺序预览；不是导航路线','Daily sequence preview; not navigation')}" data-route-state="unverified"><ol>${names.map((name,index)=>`<li><b>${index+1}</b><span>${e(name)}</span></li>`).join('')}</ol></div>`;
}

export function renderTripSections(experience,language='zh'){
 const transport=experience.transport.options.map(option=>{const title=displayLabel(option.mode,language),primary=option.allowed&&option.mode===experience.transport.preferredMode;
  const fit=!option.allowed?label(language,'不符合已选交通限定','Excluded by your transport requirement'):option.suitability==='not_applicable'?label(language,'不适用','Not applicable'):primary?label(language,'优先推荐','Recommended'):option.suitability==='medium'?label(language,'可选','Alternative'):label(language,'不优先','Lower priority');
  let verification=option.verification.status==='verified'&&option.verification.source==='live'?`${label(language,'已核验','Verified')} · Duffel · ${option.currency==='CNY'?'¥'+Math.round(option.price).toLocaleString('en-US'):label(language,'价格待核验','Price unverified')}`:option.quote?`${label(language,'演示参考','Demo reference')} · ${option.currency==='CNY'?'¥'+Math.round(option.price).toLocaleString('en-US'):label(language,'价格待核验','Price unverified')}`:option.verification.status==='partially_verified'?label(language,'入口航班已核验 · 接驳与总价待核验','Entry flight verified · connection and total cost unverified'):option.suitability==='not_applicable'?'':`${option.mode==='train'?label(language,'实时车次与票价暂未接入 · ','Live schedules and fares unavailable · '):option.mode==='self_drive'?label(language,'未接入路线、路费与驾车时间 · ','Route, tolls and drive time unavailable · '):''}${label(language,'预算','Cost')}：${band(option.costBand,language)} · ${label(language,'耗时','Time')}：${band(option.durationBand,language)} · ${label(language,'精确数据待接入','exact data unavailable')}`;
  const flight=option.mode==='flight'&&option.quote?renderFlightDetails(option.quote,option.verification.source,language,{from:displayCity(experience.trip.origin,language),to:displayCity(experience.trip.destination,language)}):'';
  const routeAction=option.mode!=='flight'&&option.suitability!=='not_applicable'?`<a class="trip-link-action" href="${e(navigationForCountry(destinationIdentity(experience.trip.destination).countryNames.en).directionsUrl({names:{en:experience.trip.destination}}))}" target="_blank" rel="noopener noreferrer">${label(language,'查看路线','View route')}</a>`:'';
  const stateClass=!option.allowed||option.suitability==='not_applicable'?' transport-muted':primary?' transport-primary':option.verification.status==='verified'?' transport-available':' transport-unverified';
  const icon={flight:'✈',train:'▰',self_drive:'◆'}[option.mode];return `<div class="transport-row${stateClass}"><div><i aria-hidden="true">${icon}</i><strong>${e(title)}</strong><span>${e(fit)}</span></div><div class="transport-detail"><p>${e(verification)}</p>${flight}${routeAction}</div></div>`;
 }).join('');
 const nav=navigationForCountry(destinationIdentity(experience.trip.destination).countryNames.en);
 const itinerary=experience.itinerary.days.map(day=>{const activities=(day.activities||[]).map(activity=>{const planning=activity.place.source==='planning_template',user=activity.place.source==='user';return `<div class="trip-activity"><time>${user?label(language,'时间待安排','Time to arrange'):`${e(activity.startTime)}–${e(activity.endTime)}`}</time><div><strong>${e(activity.place.names[language==='zh'?'zh':'en'])}</strong><small>${user?label(language,'你添加的地点 · 待核验','Your place · unverified'):planning?label(language,'规划方向 · 具体地点待确认','Planning direction · place to confirm'):activity.openingHoursState==='checked'?label(language,'营业时间已核验','Opening hours checked'):label(language,'营业时间待确认','Opening hours to confirm')}</small><div class="trip-activity-actions">${user||planning?'':`<a href="${e(nav.mapUrl(activity.place))}" target="_blank" rel="noopener noreferrer">${label(language,'查看地图','View map')}</a><a href="${e(nav.directionsUrl(activity.place))}" target="_blank" rel="noopener noreferrer">${label(language,'导航','Navigate')}</a>`}<button type="button" data-trip-action="swap" data-day="${day.day}" data-activity="${e(activity.id)}">${label(language,'换一个','Swap')}</button><button type="button" data-trip-action="remove" data-day="${day.day}" data-activity="${e(activity.id)}">${label(language,'删除','Remove')}</button></div></div></div>`;}).join('');
  const routeSummary=day.routeState==='verified'?`<p class="route-summary">${label(language,'今日移动约','Today’s travel: about')} ${(day.routeDistanceMeters/1000).toFixed(1)} km · ${label(language,'交通约','travel about')} ${day.routeDurationMinutes} min</p>`:'';
  return `<li class="itinerary-day" data-trip-day="${day.day}"><div class="itinerary-day-head"><b>${label(language,'第','Day ')}${day.day}${language==='zh'?'天':''}</b><strong>${e(day.labels[language==='zh'?'zh':'en'])}</strong><button type="button" data-trip-action="adjust-day" data-day="${day.day}">${label(language,'调整这一天','Adjust day')}</button></div><div class="itinerary-day-layout"><div>${activities}</div><div>${renderRoutePreview(day,language)}${routeSummary}</div></div><button type="button" class="trip-add-wish" data-trip-action="add-wish" data-day="${day.day}">＋ ${label(language,'我有想去的地方','I have a place in mind')}</button></li>`;}).join('');
 const stay=experience.stay,primary=stay.primaryArea||stay.areas[0],alternatives=stay.areas.map((area,index)=>`<li class="${index===0?'active':''}"><strong>${e(area.labels[language==='zh'?'zh':'en'])}</strong><span>${index===0?label(language,'最适合当前方案','Best for this plan'):area.role==='quiet'?label(language,'更安静','Quieter'):area.role==='value'?label(language,'更省预算','Better value'):label(language,'更方便','More convenient')}</span></li>`).join('');
 return `<section class="trip-module" data-trip-module="transport"><div class="trip-module-heading"><span>02</span><h3>${label(language,'怎么去','Transport')}</h3></div><div class="transport-rows">${transport}</div></section><section class="trip-module" data-trip-module="stay"><div class="trip-module-heading"><span>03</span><h3>${label(language,'住哪里更合适','Where to stay')}</h3></div><p class="trip-module-intro"><strong>${label(language,'推荐住：','Recommended area: ')}${e(primary?.labels[language==='zh'?'zh':'en']||'')}</strong><br>${e(stay.reason?.[language==='zh'?'zh':'en']||'')}</p><ul class="stay-options">${alternatives}</ul><button type="button" class="stay-cta" data-trip-action="stay">${label(language,'查看住宿','View stays')}</button><p class="stay-feedback trip-availability" aria-live="polite">${label(language,'住宿实时价格与库存暂未接入','Live hotel prices and inventory are not connected')}</p></section><section class="trip-module" data-trip-module="itinerary"><div class="trip-module-heading"><span>04</span><h3>${label(language,'怎么玩','Itinerary')}</h3></div><p class="trip-module-intro">${label(language,'途米已经排好一套基础行程，你可以从这里修改。','Timing has prepared a complete starting itinerary. Edit it from here.')}</p><ol class="itinerary-days">${itinerary}</ol><p class="trip-availability">${experience.itinerary.status==='planning_skeleton'?label(language,'当前为可编辑的行程骨架 · 具体地点、营业时间与路线待确认。','Editable itinerary skeleton · exact places, hours and routes remain unverified.'):label(language,'地点名称来自精选目录 · 营业时间与路线未核验，行程时间为建议。','Place names from a curated catalog · opening hours and routes unverified; times are suggestions.')}</p></section>`;
}
